CREATE TRIGGER RefUNLOCO_Version_Create
	ON RefUNLOCO
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RL_PK, 'RL'
	FROM inserted
GO
CREATE TRIGGER RefUNLOCO_Version_Update
	ON RefUNLOCO
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RL_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefUNLOCO_DataChangeHistory
	ON RefUNLOCO
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT RL_PK, 'RL' FROM inserted
	UNION
	SELECT RL_PK, 'RL' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefUNLOCO_DataProcessingResult_Delete
	ON RefUNLOCO
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.RL_PK
	END
